    String[][] mcqs(String level) { String[][] easy =  { { "What is 15% of 200?", "20", "25", "30", "35", "C", "15% of 200 is 30." } , {
                "Find next: 2,4,8,16,?", "20", "24", "30", "32", "D", "Every number is multiplied by 2." } , { "₹12 × 5 = ?", "₹50", "₹60", "₹62", "₹72", "B", "12 × 5 = ₹60." } , { "Which number is odd?", "9", "16", "25", "27", "D", "27 is not a perfect square." } , { "CAT is DBU. DOG is?", "EPH", "EOG", "DPH", "FPH", "A", "Each letter moves forward by one." } , { "60 km in 1 hour. 3 hours?", "120", "150", "180", "200", "C", "60 × 3 = 180." } , { "Synonym of rapid?", "Slow", "Quick", "Quiet", "Weak", "B", "Rapid means quick." } , { "3/4 of 80?", "40", "50", "60", "70", "C", "80 × 3/4 = 60." } , { "A,C,E,G,?", "H", "I", "J", "K", "B", "One letter is skipped." } , { "12 boys + 18 girls?", "28", "30", "32", "36", "B", "12 + 18 = 30." } };
        String[][] medium =  { { "20% increase gives 120. Original?", "90", "96", "100", "110", "C", "120 / 1.2 = 100." } , { "3,8,15,24,35,?", "44", "46", "48", "50", "C", "Differences are 5,7,9,11,13." } , {
                "A:B=3:5, total=64. B?", "24", "32", "40", "48", "C", "B is 40." } , { "150 km in 2.5 hours?", "50", "55", "60", "65", "C", "150 / 2.5 = 60." } , { "All roses are flowers. Certain?", "All roses fade", "Some roses fade", "All roses are flowers", "No flowers are roses", "C", "Given statement guarantees this." } , { "Average of 12,18,20,30?", "18", "20", "22", "24", "B", "80 / 4 = 20." } , { "₹800 with 15% discount?", "₹620", "₹660", "₹680", "₹700", "C", "Sale price = ₹680." } , { "Yesterday Monday. Day after tomorrow?", "Tuesday", "Wednesday", "Thursday", "Friday", "C", "The answer is Thursday." } , { "A 6 days, B 3 days. Together?", "1", "2", "3", "4", "B", "Combined time is 2 days." } , {
                "4,9,19,39,?", "59", "69", "79", "89", "C", "Previous × 2 + 1." } }; String[][] hard =  { { "25% increase then 20% decrease?", "No change", "5% increase", "5% decrease", "10% decrease", "A", "1.25 × 0.80 = 1." } , { "4 red, 6 blue. Probability red?", "1/5", "2/5", "1/2", "3/5", "B", "4/10 = 2/5." } , { "x+1/x=5. x²+1/x²?", "21", "23", "25", "27", "B", "25 - 2 = 23." } , { "12 and 18 days together?", "6", "7.2", "8", "9", "B", "Combined rate is 5/36." } , { "1,2,6,24,120,?", "240", "360", "600", "720", "D", "These are factorial values." } , { "Two dice sum 7 probability?", "1/12", "1/9", "1/6", "1/3", "C", "Six outcomes out of 36." } , {
                "5 workers make 5 items in 5 hours. 10 workers?", "2.5", "5", "10", "15", "B", "Same production rate." } , { "Remainder 2 when divided by 5?", "17", "18", "20", "22", "D", "22 mod 5 = 2." } , { "60% Java,50% Python,20% both. At least one?", "70%", "80%", "90%", "110%", "C", "60 + 50 - 20 = 90." } , { "Two digit sum 9. Reverse +27?", "36", "45", "54", "63", "A", "Original number is 36." } };
        if(level.equals("Easy")) return easy; if(level.equals("Medium")) return medium; return hard; }
